ReturnCode rfalNfcDepPSL(uint8_t BRS, uint8_t FSL) {
    ReturnCode ret;
    uint16_t rxLen;
    uint8_t msgIt;
    uint8_t txBuf[NFCIP_PSLREQ_LEN + NFCIP_PSLPAY_LEN];
    uint8_t rxBuf[NFCIP_PSLRES_LEN];

    msgIt = NFCIP_PSLREQ_LEN;

    txBuf[msgIt++] = BRS;
    txBuf[msgIt++] = FSL;


    /* Send PSL REQ and wait for response                                          */

    EXIT_ON_ERR(
        ret,
        nfcipTxRx(
            NFCIP_CMD_PSL_REQ,
            txBuf,
            nfcipRWTActivation(),
            &txBuf[NFCIP_PSLREQ_LEN],
            (msgIt - NFCIP_PSLREQ_LEN),
            rxBuf,
            NFCIP_PSLRES_LEN,
            &rxLen));


    /* PSL sent, check response                                                    */

    msgIt = 0;
    rxLen = (uint16_t)(rxBuf[msgIt++]); /* use LEN byte                   */

    if(rxLen < NFCIP_PSLRES_LEN) /* Checking length: LEN + RLS_RES */
    {
        return ERR_PROTO;
    }

    if(rxBuf[msgIt++] != NFCIP_RES) /* Checking if is a response      */
    {
        return ERR_PROTO;
    }

    if(rxBuf[msgIt++] != (uint8_t)NFCIP_CMD_PSL_RES) /* Checking if is a PSL RES       */
    {
        return ERR_PROTO;
    }

    if(rxBuf[msgIt++] != gNfcip.cfg.did) /* Checking DID                   */
    {
        return ERR_PROTO;
    }

    return ERR_NONE;
}

static void lv_switch_trigger_anim(lv_obj_t * obj)
{
    LV_ASSERT_OBJ(obj, MY_CLASS);
    lv_switch_t * sw = (lv_switch_t *)obj;

    uint32_t anim_dur_full = lv_obj_get_style_anim_time(obj, LV_PART_MAIN);

    if(anim_dur_full > 0) {
        bool chk = lv_obj_get_state(obj) & LV_STATE_CHECKED;
        int32_t anim_start;
        int32_t anim_end;
        /*No animation in progress -> simply set the values*/
        if(sw->anim_state == LV_SWITCH_ANIM_STATE_INV) {
            anim_start = chk ? LV_SWITCH_ANIM_STATE_START : LV_SWITCH_ANIM_STATE_END;
            anim_end   = chk ? LV_SWITCH_ANIM_STATE_END : LV_SWITCH_ANIM_STATE_START;
        }
        /*Animation in progress. Start from the animation end value*/
        else {
            anim_start = sw->anim_state;
            anim_end   = chk ? LV_SWITCH_ANIM_STATE_END : LV_SWITCH_ANIM_STATE_START;
        }
        /*Calculate actual animation duration*/
        uint32_t anim_dur = (anim_dur_full * LV_ABS(anim_start - anim_end)) / LV_SWITCH_ANIM_STATE_END;

        /*Stop the previous animation if it exists*/
        lv_anim_del(sw, NULL);

        lv_anim_t a;
        lv_anim_init(&a);
        lv_anim_set_var(&a, sw);
        lv_anim_set_exec_cb(&a, lv_switch_anim_exec_cb);
        lv_anim_set_values(&a, anim_start, anim_end);
        lv_anim_set_ready_cb(&a, lv_switch_anim_ready);
        lv_anim_set_time(&a, anim_dur);
        lv_anim_start(&a);
    }
}

